cd /tmp && cat > d.py <<'EOF'
R1=[(0,0),(50,0),(50,50),(0,50)]
R2=[(25,25),(75,25),(75,75),(25,75)]
R3=[(50,50),(100,50),(100,100),(50,100)]
names={'R1':R1,'R2':R2,'R3':R3}
def edges(p,tag):
    return [(tag+str(i+1),p[i],p[(i+1)%len(p)]) for i in range(len(p))]
E=[]
for t,p in names.items(): E+=edges(p,t[1]+'e')
# pairwise segment analysis
from fractions import Fraction as F
def seg_int(a,b,c,d):
    # returns description
    import itertools
    def sub(p,q): return (p[0]-q[0],p[1]-q[1])
    def cr(u,v): return u[0]*v[1]-u[1]*v[0]
    r=sub(b,a); s=sub(d,c); denom=cr(r,s); qp=sub(c,a)
    if denom==0:
        if cr(qp,r)!=0: return None
        # collinear
        rr=r[0]*r[0]+r[1]*r[1]
        t0=F(qp[0]*r[0]+qp[1]*r[1],rr); t1=t0+F(s[0]*r[0]+s[1]*r[1],rr)
        lo,hi=min(t0,t1),max(t0,t1); lo=max(lo,F(0)); hi=min(hi,F(1))
        if lo>hi: return ('collinear-disjoint',)
        if lo==hi: return ('collinear-point-touch', (a[0]+lo*r[0], a[1]+lo*r[1]))
        return ('collinear-overlap', (a[0]+lo*r[0],a[1]+lo*r[1]),(a[0]+hi*r[0],a[1]+hi*r[1]))
    t=F(cr(qp,s),denom); u=F(cr(qp,r),denom)
    if 0<=t<=1 and 0<=u<=1:
        pt=(a[0]+t*r[0], a[1]+t*r[1])
        kind='proper-crossing' if (0<t<1 and 0<u<1) else 'endpoint-touch'
        return (kind, pt, 't=%s u=%s'%(t,u))
    return None
for i in range(len(E)):
    for j in range(i+1,len(E)):
        n1,a,b=E[i]; n2,c,d=E[j]
        if n1[0]==n2[0]: continue
        r=seg_int(a,b,c,d)
        if r and r[0]!='collinear-disjoint':
            print(n1,(a,b),n2,(c,d),'->',r)
