type P=(i64,i64);
fn shoelace(r:&[P])->i64{
    let mut s=0i64;
    for i in 0..r.len(){
        let (x1,y1)=r[i]; let (x2,y2)=r[(i+1)%r.len()];
        let t=x1*y2-x2*y1;
        s+=t;
        println!("({:>3},{:>3}) -> ({:>3},{:>3})   {:>3}*{:<3} - {:>3}*{:<3} = {:>6} - {:>6} = {:>6}   running 2A = {}",x1,y1,x2,y2,x1,y2,x2,y1,x1*y2,x2*y1,t,s);
    }
    s
}
fn pip(px:f64,py:f64,poly:&[P])->bool{
    let mut c=false; let n=poly.len();
    for i in 0..n{
        let (x1,y1)=poly[i]; let (x2,y2)=poly[(i+1)%n];
        let (x1,y1,x2,y2)=(x1 as f64,y1 as f64,x2 as f64,y2 as f64);
        if (y1>py)!=(y2>py){
            let xin=x1+(py-y1)*(x2-x1)/(y2-y1);
            if px<xin {c=!c;}
        }
    }
    c
}
fn in_union(x:f64,y:f64)->bool{
    (x>=0.0&&x<=50.0&&y>=0.0&&y<=50.0)||(x>=25.0&&x<=75.0&&y>=25.0&&y<=75.0)||(x>=50.0&&x<=100.0&&y>=50.0&&y<=100.0)
}
fn main(){
    let ring:Vec<P>=vec![(0,0),(50,0),(50,25),(75,25),(75,50),(100,50),(100,100),(50,100),(50,75),(25,75),(25,50),(0,50)];
    let s=shoelace(&ring);
    println!("2A = {}   signed area = {}", s, (s as f64)/2.0);
    // raster: union area, and agreement ring vs union
    let n=1000; let h=100.0/(n as f64); let mut cnt=0u64; let mut bad=0u64;
    for i in 0..n{ for j in 0..n{
        let x=((i as f64)+0.5)*h; let y=((j as f64)+0.5)*h;
        let u=in_union(x,y); let r=pip(x,y,&ring);
        if u {cnt+=1;} if u!=r {bad+=1;}
    }}
    println!("raster union area = {}", (cnt as f64)*h*h);
    println!("mismatched cells (ring vs union) = {}", bad);
    // winding numbers around (50,50)
    let rects=[[(0i64,0i64),(50,0),(50,50),(0,50)],[(25,25),(75,25),(75,75),(25,75)],[(50,50),(100,50),(100,100),(50,100)]];
    for (dx,dy) in [(-0.5,-0.5),(0.5,-0.5),(0.5,0.5),(-0.5,0.5)]{
        let x=50.0+dx; let y=50.0+dy;
        let mut w=0; for r in rects.iter(){ if pip(x,y,r){w+=1;} }
        println!("point ({}, {}) winding = {}", x,y,w);
    }
    // orientation of each input rect
    for (k,r) in rects.iter().enumerate(){
        let mut s=0i64; for i in 0..4{let (x1,y1)=r[i];let(x2,y2)=r[(i+1)%4]; s+=x1*y2-x2*y1;}
        println!("rect{} signed area = {}", k+1, (s as f64)/2.0);
    }
}
