type P=(i64,i64);
fn cr(u:P,v:P)->i64{u.0*v.1-u.1*v.0}
fn sub(p:P,q:P)->P{(p.0-q.0,p.1-q.1)}
fn dot(u:P,v:P)->i64{u.0*v.0+u.1*v.1}
fn main(){
    let r1:[P;4]=[(0,0),(50,0),(50,50),(0,50)];
    let r2:[P;4]=[(25,25),(75,25),(75,75),(25,75)];
    let r3:[P;4]=[(50,50),(100,50),(100,100),(50,100)];
    let mut e:Vec<(String,P,P)>=vec![];
    for (tag,r) in [("R1",&r1),("R2",&r2),("R3",&r3)]{
        for i in 0..4{ e.push((format!("{}e{}",tag,i+1), r[i], r[(i+1)%4])); }
    }
    for i in 0..e.len(){ for j in (i+1)..e.len(){
        let (n1,a,b)=(&e[i].0,e[i].1,e[i].2);
        let (n2,c,d)=(&e[j].0,e[j].1,e[j].2);
        if n1[..2]==n2[..2] {continue;}
        let r=sub(b,a); let s=sub(d,c); let den=cr(r,s); let qp=sub(c,a);
        if den==0{
            if cr(qp,r)!=0 {continue;}
            let rr=dot(r,r) as f64;
            let t0=(dot(qp,r) as f64)/rr; let t1=t0+(dot(s,r) as f64)/rr;
            let (lo,hi)=(t0.min(t1).max(0.0), t0.max(t1).min(1.0));
            if lo>hi {continue;}
            let pl=(a.0 as f64+lo*r.0 as f64, a.1 as f64+lo*r.1 as f64);
            let ph=(a.0 as f64+hi*r.0 as f64, a.1 as f64+hi*r.1 as f64);
            if (hi-lo).abs()<1e-12 {
                println!("COLLINEAR-POINT-TOUCH  {} {:?}-{:?}  |  {} {:?}-{:?}  at ({},{})",n1,a,b,n2,c,d,pl.0,pl.1);
            } else {
                println!("COLLINEAR-OVERLAP      {} {:?}-{:?}  |  {} {:?}-{:?}  seg ({},{})-({},{}) len {}",n1,a,b,n2,c,d,pl.0,pl.1,ph.0,ph.1,((ph.0-pl.0).powi(2)+(ph.1-pl.1).powi(2)).sqrt());
            }
            continue;
        }
        let t=(cr(qp,s) as f64)/(den as f64); let u=(cr(qp,r) as f64)/(den as f64);
        if t>=0.0&&t<=1.0&&u>=0.0&&u<=1.0{
            let pt=(a.0 as f64+t*r.0 as f64, a.1 as f64+t*r.1 as f64);
            let kind = if t>0.0&&t<1.0&&u>0.0&&u<1.0 {"PROPER-X-CROSSING (both interiors)"}
                       else if (t>0.0&&t<1.0)||(u>0.0&&u<1.0) {"T-JUNCTION (vertex on edge interior)"}
                       else {"VERTEX-VERTEX TOUCH"};
            println!("{:<36} {} {:?}-{:?}  |  {} {:?}-{:?}  at ({},{})  t={} u={}",kind,n1,a,b,n2,c,d,pt.0,pt.1,t,u);
        }
    }}
    // vertex containment classification
    println!("---- vertex vs other rects (strict interior of face) ----");
    let rects=[("R1",r1),("R2",r2),("R3",r3)];
    for (tn,tr) in rects.iter(){
        for v in tr.iter(){
            for (on,or) in rects.iter(){
                if tn==on {continue;}
                let xs:Vec<i64>=or.iter().map(|p|p.0).collect(); let ys:Vec<i64>=or.iter().map(|p|p.1).collect();
                let (x0,x1)=(*xs.iter().min().unwrap(),*xs.iter().max().unwrap());
                let (y0,y1)=(*ys.iter().min().unwrap(),*ys.iter().max().unwrap());
                if v.0>x0&&v.0<x1&&v.1>y0&&v.1<y1 {println!("vertex {:?} of {} is STRICTLY INSIDE face of {}",v,tn,on);}
                else if v.0>=x0&&v.0<=x1&&v.1>=y0&&v.1<=y1 {println!("vertex {:?} of {} is ON BOUNDARY of {}",v,tn,on);}
            }
        }
    }
}
